#[test]
fn test_a_candidate_is_a_group_with_no_word() {
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(300, 120, 3);
    let rules: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cand: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    spx_paper(b);
    spx_line(b, 20, 280, 100);
    spx_zig(b, 40, 98, 150, 24, 36, 20, 40, 120);
    spx_rule(rules, 20, 280, 100);
    crate::testport::assert_eq(spx_find(rules, ow, et, b, cand), 1, "a signature");
    crate::testport::assert_eq(sp_record(3, cand, cg), 1, "one group");
    crate::testport::assert_eq(cg_get(cg, 0, cgf_page()), 4, "of page 4 (the argument is 0-based)");
    crate::testport::assert_eq(cg_get(cg, 0, cgf_ocount()), 0, "no word");
    crate::testport::assert_eq(cg_get(cg, 0, cgf_flags()), (plg_in_seal() + plg_seal_px()) + plg_seal_sig(), "flagged in-seal, seal-px and seal-sig");
    crate::testport::assert_eq(cg_get(cg, 0, cgf_rot()), 10, "its colour code: blue");
    crate::testport::assert_eq(cg_get(cg, 0, cgf_x0()), crate::port::cells_at(cand, 2), "its box is the candidate's");
}
#[test]
fn test_the_lines_the_strokes_made_are_not_the_pages_text() {
    let cand: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ol: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let scr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    while crate::port::cells_len(cand) < sp_w() {
        crate::port::cells_push(cand, 0);
    }
    crate::port::cells_set(cand, 0, 3);
    crate::port::cells_set(cand, 2, 1000);
    crate::port::cells_set(cand, 3, 1000);
    crate::port::cells_set(cand, 4, 7000);
    crate::port::cells_set(cand, 5, 4000);
    // line 1: two words inside, the engine 300 sure (the strokes read as letters); line 2: one word inside at 900 (a typed name under the strokes); line 3: elsewhere
    ow_new(ow, 1, 1500, 1500, 3000, 2500, 1500, 2500, 3000, 2500, 0, 0, 0, 1, 0, 300, -1);
    ow_new(ow, 1, 3500, 1500, 5000, 2500, 3500, 2500, 5000, 2500, 0, 0, 0, 1, 0, 300, -1);
    ow_new(ow, 1, 2000, 3000, 4000, 3800, 2000, 3800, 4000, 3800, 0, 0, 0, 1, 0, 900, -1);
    ow_new(ow, 1, 30000, 30000, 32000, 31000, 30000, 31000, 32000, 31000, 0, 0, 0, 1, 0, 900, -1);
    ol_new(ol, 1, 1500, 1500, 5000, 2500, 1500, 2500, 5000, 2500, 0, 0, 0, 2);
    ol_new(ol, 1, 2000, 3000, 4000, 3800, 2000, 3800, 4000, 3800, 0, 0, 2, 1);
    ol_new(ol, 1, 30000, 30000, 32000, 31000, 30000, 31000, 32000, 31000, 0, 0, 3, 1);
    while crate::port::cells_len(scr) < (sc_sel_base() + 8) {
        crate::port::cells_push(scr, 0);
    }
    crate::port::cells_set(scr, sc_sel_base(), 0);
    crate::port::cells_set(scr, sc_sel_base() + 1, 1);
    crate::port::cells_set(scr, sc_sel_base() + 2, 2);
    crate::testport::assert_eq(sp_drop_lines(scr, 3, ol, ow, cand), 2, "the strokes' line is out; the typed name the engine is sure of and the line elsewhere stay");
    crate::testport::assert_eq(crate::port::cells_at(scr, sc_sel_base()), 1, "the typed name first");
    crate::testport::assert_eq(crate::port::cells_at(scr, sc_sel_base() + 1), 2, "then the other");
}
#[test]
fn test_unadopted_receipt_words_cannot_mask_the_baseline_signature_pixels() {
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(300, 120, 3);
    let rules: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cand: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let views: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mask: &mut crate::port::Cells = &mut crate::port::Cells::new();
    spx_paper(b);
    spx_line(b, 20, 280, 100);
    spx_zig(b, 40, 98, 150, 24, 36, 20, 40, 120);
    spx_rule(rules, 20, 280, 100);
    vw_new(views, 1, vk_render(), -1, -1, 300, 120, 7200, 0, -1, 0, 0, 0, 0, 0);
    crate::port::cells_push(et, 83);
    crate::port::cells_push(et, 105);
    crate::port::cells_push(et, 103);
    ow_new(ow, 1, 3000, 5500, 21000, 10500, 3000, 10500, 21000, 10500, 0, 0, 0, 3, 0, 900, -1);
    crate::testport::assert_eq(sp_find(1, views, 0, rules, ow, et, b, 61200, cand, mask), 0, "an admitted confident reading still masks text");
    crate::testport::assert_eq(sp_find_without(1, views, 0, rules, ow, et, b, 61200, 0, 1, cand, mask), 1, "an unadopted reading cannot erase a signature and restore its rejected text");
    crate::testport::assert_eq(sp_find_without(1, views, 0, rules, ow, et, b, 61200, 1, 1, cand, mask), 0, "the interval is half open; other readings still mask text");
    crate::testport::assert_eq(ow_count(ow), 1, "the raw alternative remains evidence");
    crate::testport::assert_eq(ow_get(ow, 0, hd_conf()), 900, "raw confidence is unchanged");
}
